import {
  ALPHABET, DISTRIBUTIONS, JOKERS_PER_BAG, MIN_BAG_FOR_EXCHANGE, RACK_SIZE, isLanguage,
} from './constants.js';
import { analyzeMove, createEmptyBoard } from './move.js';

export class GameError extends Error {
  constructor(code, details) {
    super(code);
    this.code = code;
    if (details !== undefined) this.details = details;
  }
}

export function createBag(lang, rng = Math.random) {
  const dist = DISTRIBUTIONS[lang];
  if (!dist) throw new GameError('UNKNOWN_LANGUAGE');
  const bag = [];
  let n = 0;
  for (const [letter, [count, value]] of Object.entries(dist)) {
    for (let i = 0; i < count; i++) bag.push({ id: `t${n++}`, letter, value, joker: false });
  }
  for (let i = 0; i < JOKERS_PER_BAG; i++) bag.push({ id: `t${n++}`, letter: '', value: 0, joker: true });
  shuffle(bag, rng);
  return bag;
}

/**
 * @param {{ playerIds: string[], lang: 'FR' | 'EN', turnDurationMs: number, rng?: () => number, now?: number }} opts
 */
export function createGame({ playerIds, lang, turnDurationMs, rng = Math.random, now = Date.now() }) {
  if (!isLanguage(lang)) throw new GameError('UNKNOWN_LANGUAGE');
  if (!Array.isArray(playerIds) || playerIds.length < 2) throw new GameError('NOT_ENOUGH_PLAYERS');
  const bag = createBag(lang, rng);
  const order = [...playerIds];
  shuffle(order, rng);
  const players = order.map((id) => ({
    id,
    rack: draw(bag, RACK_SIZE),
    score: 0,
    stats: { moves: 0, bingos: 0, passes: 0, exchanges: 0, bestMove: null },
  }));
  return {
    lang,
    board: createEmptyBoard(),
    bag,
    players,
    turnIndex: 0,
    turnNumber: 1,
    turnDurationMs,
    turnStartedAt: now,
    turnEndsAt: turnDurationMs > 0 ? now + turnDurationMs : null,
    scorelessTurns: 0,
    status: 'playing',
    log: [],
    lastMove: null,
    results: null,
    startedAt: now,
  };
}

export function currentPlayer(game) {
  return game.players[game.turnIndex];
}

function assertTurn(game, playerId) {
  if (game.status !== 'playing') throw new GameError('GAME_OVER');
  const player = game.players.find((p) => p.id === playerId);
  if (!player) throw new GameError('NOT_IN_GAME');
  if (currentPlayer(game).id !== playerId) throw new GameError('NOT_YOUR_TURN');
  return player;
}

/**
 * Resolves client placements ({ tileId, x, y, letter? }) against the player's rack.
 * A joker must be given the letter it stands for; that letter is then locked on the board.
 */
export function resolvePlacements(rack, placements) {
  if (!Array.isArray(placements) || placements.length === 0) throw new GameError('NO_TILES');
  const used = new Set();
  return placements.map((pl) => {
    const tile = rack.find((t) => t.id === pl?.tileId);
    if (!tile) throw new GameError('TILE_NOT_IN_RACK');
    if (used.has(tile.id)) throw new GameError('DUPLICATE_TILE');
    used.add(tile.id);
    let letter = tile.letter;
    if (tile.joker) {
      letter = typeof pl.letter === 'string' ? pl.letter.toUpperCase() : '';
      if (letter.length !== 1 || !ALPHABET.includes(letter)) throw new GameError('JOKER_LETTER_REQUIRED');
    }
    return { x: pl.x, y: pl.y, tileId: tile.id, letter, value: tile.value, joker: tile.joker };
  });
}

/**
 * @param {(word: string) => boolean} isWord dictionary lookup for the game's language
 */
export function playTiles(game, playerId, placements, { isWord, now = Date.now() }) {
  const player = assertTurn(game, playerId);
  const resolved = resolvePlacements(player.rack, placements);
  const analysis = analyzeMove(game.board, resolved);
  if (!analysis.ok) throw new GameError(analysis.error);

  const invalid = analysis.words.map((w) => w.word).filter((w) => !isWord(w));
  if (invalid.length > 0) throw new GameError('INVALID_WORDS', { words: invalid });

  for (const p of resolved) {
    game.board[p.y][p.x] = {
      letter: p.letter, value: p.value, joker: p.joker, tileId: p.tileId, by: playerId, turn: game.turnNumber,
    };
  }
  const usedIds = new Set(resolved.map((p) => p.tileId));
  player.rack = player.rack.filter((t) => !usedIds.has(t.id));
  player.rack.push(...draw(game.bag, RACK_SIZE - player.rack.length));
  player.score += analysis.score;

  // Cells are kept so clients can point at a word on the board from the history.
  const words = analysis.words.map((w) => ({ word: w.word, score: w.score, cells: w.cells.map(({ x, y }) => ({ x, y })) }));
  player.stats.moves += 1;
  if (analysis.bingo) player.stats.bingos += 1;
  if (!player.stats.bestMove || analysis.score > player.stats.bestMove.score) {
    player.stats.bestMove = { word: words[0].word, score: analysis.score };
  }

  const move = {
    type: 'play',
    playerId,
    turn: game.turnNumber,
    at: now,
    score: analysis.score,
    bingo: analysis.bingo,
    words,
    tiles: resolved.map(({ x, y, letter, value, joker }) => ({ x, y, letter, value, joker })),
  };
  game.scorelessTurns = 0;
  record(game, move);

  if (player.rack.length === 0 && game.bag.length === 0) finish(game, 'OUT', player.id, now);
  else advance(game, now);
  return move;
}

export function passTurn(game, playerId, { reason = 'pass', now = Date.now() } = {}) {
  const player = assertTurn(game, playerId);
  player.stats.passes += 1;
  const move = { type: reason === 'timeout' ? 'timeout' : 'pass', playerId, turn: game.turnNumber, at: now, score: 0 };
  scoreless(game, move, now);
  return move;
}

export function exchangeTiles(game, playerId, tileIds, { rng = Math.random, now = Date.now() } = {}) {
  const player = assertTurn(game, playerId);
  if (!Array.isArray(tileIds) || tileIds.length === 0) throw new GameError('NO_TILES');
  if (game.bag.length < MIN_BAG_FOR_EXCHANGE) throw new GameError('BAG_TOO_SMALL');
  const ids = new Set(tileIds);
  if (ids.size !== tileIds.length) throw new GameError('DUPLICATE_TILE');
  const returned = player.rack.filter((t) => ids.has(t.id));
  if (returned.length !== ids.size) throw new GameError('TILE_NOT_IN_RACK');

  // Official rule: draw the new tiles before putting the old ones back.
  const drawn = draw(game.bag, returned.length);
  player.rack = [...player.rack.filter((t) => !ids.has(t.id)), ...drawn];
  game.bag.push(...returned);
  shuffle(game.bag, rng);

  player.stats.exchanges += 1;
  const move = { type: 'exchange', playerId, turn: game.turnNumber, at: now, score: 0, count: returned.length };
  scoreless(game, move, now);
  return move;
}

function scoreless(game, move, now) {
  record(game, move);
  game.scorelessTurns += 1;
  // Every player passed or exchanged twice in a row.
  if (game.scorelessTurns >= game.players.length * 2) finish(game, 'PASSES', null, now);
  else advance(game, now);
}

function record(game, move) {
  game.log.push(move);
  game.lastMove = move;
}

function advance(game, now) {
  game.turnIndex = (game.turnIndex + 1) % game.players.length;
  game.turnNumber += 1;
  game.turnStartedAt = now;
  game.turnEndsAt = game.turnDurationMs > 0 ? now + game.turnDurationMs : null;
}

function finish(game, reason, finisherId, now) {
  let leftover = 0;
  const adjustments = {};
  for (const p of game.players) {
    const penalty = p.rack.reduce((sum, t) => sum + t.value, 0);
    adjustments[p.id] = -penalty;
    p.score -= penalty;
    leftover += penalty;
  }
  if (finisherId) {
    const finisher = game.players.find((p) => p.id === finisherId);
    finisher.score += leftover;
    adjustments[finisherId] += leftover;
  }
  const best = Math.max(...game.players.map((p) => p.score));
  game.status = 'finished';
  game.turnEndsAt = null;
  game.results = {
    reason,
    finisherId,
    endedAt: now,
    winnerIds: game.players.filter((p) => p.score === best).map((p) => p.id),
    ranking: [...game.players]
      .sort((a, b) => b.score - a.score)
      .map((p) => ({ playerId: p.id, score: p.score, adjustment: adjustments[p.id], stats: p.stats })),
  };
}

export function shuffle(arr, rng = Math.random) {
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(rng() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}

function draw(bag, n) {
  return bag.splice(Math.max(0, bag.length - n), n);
}
